component.css:
.mt{--a:#ffce8a;--p:rgba(9,13,20,.6);width:100%;max-width:960px;margin:0 auto;font-family:"Noto Sans SC","PingFang SC","Hiragino Sans GB","Microsoft YaHei",sans-serif;user-select:none;-webkit-user-select:none;-webkit-tap-highlight-color:transparent}
.mt b{font-weight:inherit}.mt i,.mt em{font-style:normal}.mt u,.mt s{text-decoration:none}
.stage{position:relative;width:100%;aspect-ratio:16/9;container-type:inline-size;background:#05070c;border-radius:min(1.8cqw,12px);overflow:hidden;box-shadow:0 12px 44px #0009,0 0 0 1px #ffffff14;transition:opacity 1.3s,filter .15s}
.stage.bye{opacity:0}
.stage.fl{filter:invert(1) hue-rotate(160deg)}
.stage.fs{border-radius:0}
.bg{position:absolute;inset:0;background-size:cover;background-position:center;animation:kb 24s ease-in-out infinite alternate}
@keyframes kb{0%{transform:scale(1.05)}100%{transform:scale(1.16)}}
.film{position:absolute;inset:0;z-index:8;pointer-events:none;background:radial-gradient(125% 125% at 50% 42%,transparent 55%,rgba(2,4,8,.5))}
.scr{position:absolute;inset:0;opacity:0;visibility:hidden;transition:.55s}
.scr.on{opacity:1;visibility:visible}
.s-boot video{width:100%;height:100%;object-fit:cover;display:block}
.bl{position:absolute;left:2.6cqw;bottom:2.2cqw;z-index:3;font-size:max(1.5cqw,9px);letter-spacing:.4cqw;color:#fff9;text-shadow:0 1px 6px #000c}
.veil{position:absolute;inset:0;z-index:3;display:flex;align-items:flex-end;justify-content:center;padding-bottom:7cqw;pointer-events:none}
#tap{display:none;font-size:max(2.2cqw,11px);letter-spacing:.5cqw;color:#ffe9c4;background:rgba(8,11,17,.66);border:1px solid #ffd69680;padding:1.3cqw 3.4cqw;border-radius:99px;backdrop-filter:blur(4px);animation:blink 1.5s infinite}
#tap.on{display:block}
@keyframes blink{50%{opacity:.35}}
.ttl{position:absolute;left:5.4cqw;top:6cqw;z-index:3;color:#fff;animation:fu .9s .15s both}
.ttl em{display:block;font-size:max(2cqw,10px);letter-spacing:.7cqw;color:#ffd9a0}
.ttl strong{display:block;margin-top:.6cqw;font-family:"Noto Serif SC","Songti SC","SimSun",Georgia,serif;font-weight:900;font-size:8.6cqw;line-height:1.12;letter-spacing:.8cqw;text-shadow:0 3px 22px #000a6b,0 0 3px #ffbe6e73}
.ttl span{display:block;margin-top:1cqw;font-size:max(1.4cqw,8px);letter-spacing:1.2cqw;color:#fffc7}
@keyframes fu{0%{opacity:0;transform:translateY(1.6cqw)}100%{opacity:1;transform:none}}
.menu{position:absolute;left:6cqw;bottom:7.6cqw;z-index:3;display:flex;flex-direction:column;gap:1.5cqw}
.menu b{position:relative;display:flex;align-items:baseline;gap:1.3cqw;padding:.85cqw 1.6cqw .85cqw 1.1cqw;color:#f4f6fb;font-size:max(2.5cqw,11px);font-weight:600;letter-spacing:.3cqw;border-left:.45cqw solid transparent;cursor:pointer;transition:.3s;text-shadow:0 1px 8px #000b}
.menu b::after{content:"";position:absolute;left:0;bottom:.35cqw;height:1px;width:0;background:linear-gradient(90deg,var(--a),transparent);transition:width .35s}
.menu b u{color:var(--a);font-size:.6em}
.menu b s{color:#fff9;font-size:.5em}
.menu b.sel{color:#ffe2b0;border-left-color:var(--a)}
.menu b.sel::after{width:100%}
@media(hover:hover){.menu b:hover{color:#ffe2b0;border-left-color:var(--a);transform:translateX(.9cqw)}.menu b:hover::after{width:100%}}
.dust{position:absolute;inset:0;z-index:2;pointer-events:none;overflow:hidden}
.dust::before,.dust::after{content:"";position:absolute;width:2px;height:2px;border-radius:50%;animation:drift 18s linear infinite}
.dust::before{box-shadow:8cqw 40cqw 0 0 #ffdea6d9,20cqw 12cqw 0 0 #ffdea680,34cqw 50cqw 0 1px #ffdea6b3,52cqw 30cqw 0 0 #ffdea673,66cqw 46cqw 0 1px #ffdea699,78cqw 16cqw 0 0 #ffdea680}
.dust::after{width:1px;height:1px;animation-duration:26s;animation-delay:-9s;box-shadow:14cqw 52cqw 0 0 #ffecc899,30cqw 34cqw 0 0 #ffecc866,44cqw 18cqw 0 0 #ffecc88c,58cqw 44cqw 0 0 #ffecc859}
@keyframes drift{0%{transform:translateY(3cqw);opacity:0}12%,88%{opacity:1}100%{transform:translateY(-7cqw);opacity:0}}
.pt{position:absolute;left:19cqw;top:4.4cqw;z-index:4;color:#fff;font-size:max(4.4cqw,15px);font-weight:800;letter-spacing:.9cqw;text-shadow:0 2px 14px #000a;opacity:0;transform:translateY(1.4cqw);transition:.5s .08s}
.pt s{display:block;margin-top:.5cqw;font-size:max(1.7cqw,9px);letter-spacing:.55cqw;color:#ffd9a0;font-weight:600}
.scr.on .pt{opacity:1;transform:none}
.snav{position:absolute;left:2.2cqw;top:25cqw;z-index:5;display:none;flex-direction:column;gap:1cqw;width:15cqw}
[data-page=load] .snav,[data-page=gal] .snav,[data-page=set] .snav{display:flex}
.snav b{display:flex;gap:.9cqw;align-items:baseline;padding:1.2cqw;border-radius:.8cqw;background:var(--p);border:1px solid #ffffff24;color:#eef2f8;font-size:max(1.75cqw,9px);font-weight:600;cursor:pointer;backdrop-filter:blur(6px);transition:.25s;overflow:hidden}
.snav b u{flex:none;color:var(--a);font-size:.72em}
.snav b s{overflow:hidden;text-overflow:ellipsis;white-space:nowrap;opacity:.85}
.snav b.cur{background:#ffc47838;border-color:#ffce8aa6;color:#ffe6bd}
@media(hover:hover){.snav b:hover{border-color:#ffce8a99;transform:translateX(.4cqw)}}
.bbar{position:absolute;left:0;right:0;bottom:1.8cqw;z-index:5;display:flex;justify-content:space-between;align-items:center;padding:0 2.6cqw;font-size:max(1.7cqw,9px);letter-spacing:.25cqw;color:#ffffffee;pointer-events:none}
.bbar b{pointer-events:auto;cursor:pointer;text-shadow:0 1px 6px #000c}
#bk{display:none}
[data-page=load] #bk,[data-page=gal] #bk,[data-page=set] #bk{display:inline}
#ver{opacity:.7;cursor:pointer}
.slots,.cgs,.panes{position:absolute;left:19cqw;right:3.6cqw;top:13cqw;bottom:6.6cqw;z-index:4;display:grid;grid-template-columns:1fr 1fr 1fr;grid-template-rows:1fr 1fr;gap:1.3cqw;opacity:0;transform:translateY(1.4cqw);transition:.5s .15s}
.scr.on .slots,.scr.on .cgs,.scr.on .panes{opacity:1;transform:none}
.sv{position:relative;display:flex;flex-direction:column;justify-content:center;gap:.5cqw;padding:1.3cqw 1.6cqw;border-radius:1cqw;background:rgba(12,17,26,.6);border:1px solid #ffffff29;color:#f2f5fa;cursor:pointer;backdrop-filter:blur(5px);transition:.25s;overflow:hidden}
.sv.empty{background:rgba(12,17,26,.32);border-style:dashed}
.sv.full::before{content:"";position:absolute;left:0;top:0;bottom:0;width:.45cqw;background:linear-gradient(var(--a),#ff9d5c)}
.sv i{font-size:max(1.35cqw,8px);color:var(--a)}
.sv strong{font-size:max(1.85cqw,9px);font-weight:700;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}
.sv span{font-size:max(1.3cqw,8px);opacity:.72}
.sv .del{position:absolute;right:.7cqw;top:.7cqw;padding:.1cqw .8cqw;border:1px solid #ffffff47;border-radius:.6cqw;font-size:max(1.4cqw,8px);color:#fff8c}
.sv .del.ok{color:#ff8171;border-color:#ff8171}
@media(hover:hover){.sv:hover{border-color:#ffce8aa6;transform:translateY(-.3cqw)}}
.cg{position:relative;border-radius:1cqw;overflow:hidden;cursor:pointer;border:1px solid #ffffff29;background:var(--p);transition:.25s}
.cg img{width:100%;height:100%;object-fit:cover;display:block;transition:transform .5s}
.cg i{position:absolute;left:0;right:0;bottom:0;padding:.7cqw 1.1cqw;color:#fff;font-size:max(1.35cqw,8px);background:linear-gradient(transparent,rgba(4,7,11,.88))}
.cg .qm{position:absolute;inset:0;display:flex;align-items:center;justify-content:center;font-size:max(4.5cqw,18px);font-weight:900;color:#ffffff47}
.cg.txt{display:flex;flex-direction:column;align-items:center;justify-content:center;gap:.6cqw;background:linear-gradient(135deg,#2b2214,#0d1017);color:#ffd9a0;text-align:center;padding:1cqw;font-size:max(1.7cqw,9px);letter-spacing:.2cqw}
.cg.txt i{font-size:max(1.3cqw,8px);color:#fff7}
@media(hover:hover){.cg:hover{border-color:#ffce8ab3}.cg:hover img{transform:scale(1.08)}}
.lb{position:absolute;inset:0;z-index:10;display:none;align-items:center;justify-content:center;background:rgba(3,5,9,.9);backdrop-filter:blur(6px)}
.lb.on{display:flex}
.lb img{max-width:86%;max-height:72%;border-radius:.9cqw;box-shadow:0 10px 44px #000c;animation:fu .35s both}
.lb p{position:absolute;left:0;right:0;bottom:6.5cqw;text-align:center;color:#ffe6bd;font-size:max(1.9cqw,10px);letter-spacing:.35cqw}
#lbx{position:absolute;right:2.6cqw;top:2cqw;color:#fff;font-size:max(2.8cqw,14px);cursor:pointer}
.panes{grid-template-columns:1fr 1fr}
.pane:last-child{grid-column:1/-1}
.pane{border-radius:1cqw;background:rgba(12,17,26,.62);border:1px solid #ffffff24;padding:1.5cqw 1.8cqw;backdrop-filter:blur(6px);color:#eef2f8;overflow:hidden}
.pane h4{margin:0 0 .7cqw;font-size:max(1.55cqw,9px);letter-spacing:.35cqw;color:var(--a)}
.pane label{display:flex;align-items:center;gap:1.1cqw;font-size:max(1.5cqw,9px);padding:.85cqw 0;border-bottom:1px dashed #ffffff17}
.pane output{margin-left:auto;flex:none;color:#ffd9a0;font-variant-numeric:tabular-nums}
.pane select{margin-left:auto;flex:none;max-width:13cqw;background:#141a26;color:#ffe6bd;border:1px solid #ffffff38;border-radius:.6cqw;font-size:max(1.45cqw,9px);padding:.4cqw .7cqw;outline:none;cursor:pointer}
input[type=range]{flex:1;appearance:none;-webkit-appearance:none;min-height:4px;height:.6cqw;border-radius:99px;outline:none;cursor:pointer;background:linear-gradient(90deg,var(--a) var(--v,55%),#ffffff2e var(--v,55%))}
input[type=range]::-webkit-slider-thumb{appearance:none;-webkit-appearance:none;width:1.8cqw;height:1.8cqw;min-width:11px;min-height:11px;border-radius:50%;background:#ffe2b0;border:.16cqw solid #7a4d1c;box-shadow:0 0 8px #ffbe6e8c}
input[type=range]::-moz-range-thumb{width:1.8cqw;height:1.8cqw;border-radius:50%;background:#ffe2b0;border:.16cqw solid #7a4d1c}
.tg input{display:none}
.tg i{margin-left:auto;flex:none;width:3.6cqw;height:1.9cqw;border-radius:99px;background:#ffffff33;position:relative;transition:.25s;cursor:pointer}
.tg i::after{content:"";position:absolute;left:.25cqw;top:.25cqw;width:1.4cqw;height:1.4cqw;border-radius:50%;background:#fff;transition:.25s}
.tg input:checked+i{background:var(--a)}
.tg input:checked+i::after{transform:translateX(1.7cqw)}
.tt{position:absolute;left:50%;top:11.5cqw;z-index:12;transform:translate(-50%,-.8cqw);max-width:72%;background:rgba(8,11,17,.88);border:1px solid #ffce8a80;color:#ffe9c8;padding:1.1cqw 2.6cqw;border-radius:99px;font-size:max(1.8cqw,10px);text-align:center;opacity:0;transition:.35s;pointer-events:none;backdrop-filter:blur(6px)}
.tt.on{opacity:1;transform:translate(-50%,0)}
.rot{display:none;margin-top:.9em;text-align:center;color:#ffb765;font-size:12px;letter-spacing:1px}
@media(max-width:560px) and (orientation:portrait){.rot{display:block}}
